 imp=r['weighted_permutation_importance'];imp_order=sorted(imp,key=lambda k:imp[k]['mean_auroc_drop'],reverse=True)
 p(d,f'Permutation analysis showed the largest weighted AUROC decrease after shuffling {imp_order[0].upper()} ({imp[imp_order[0]]["mean_auroc_drop"]:.3f}), followed by {imp_order[1].upper()} ({imp[imp_order[1]]["mean_auroc_drop"]:.3f}) and {imp_order[2].upper()} ({imp[imp_order[2]]["mean_auroc_drop"]:.3f}) (Figure 6). These changes quantify model dependence in this sample rather than isolated causal effects; effects can be obscured by feature correlation or may vary across clinical settings.')
